// ── HAVAN STATUE — Bronze Founder Monument Scene ──
// Runtime: svg, w, h, bY, bCol, wc, ol, isN, mt, w1, w2, w3, sc
// Deterministic only — no Math.random()

const B = sc.sky1 || "#5B8EC4";
const Y = sc.acc  || "#C4862D";
const G = sc.ground || "#3D6B4F";
const deep = sc.sky2 || "#87CEEB";
const white = "#ffffff";
const bronze = "#9B7B4F";
const bronzeDark = "#6B4F32";
const bronzeLight = "#C4A86B";
const ww = w / 900;

const sin = (t, amp = 1, freq = 1, phase = 0) => Math.sin(t * freq + phase) * amp;
const cos = (t, amp = 1, freq = 1, phase = 0) => Math.cos(t * freq + phase) * amp;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

// ── DEFS ──
svg += `<defs>
  <filter id="fg" x="-50%" y="-50%" width="200%" height="200%">
    <feGaussianBlur stdDeviation="2.5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="sg" x="-50%" y="-50%" width="200%" height="200%">
    <feGaussianBlur stdDeviation="1.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="sh" x="-20%" y="-20%" width="140%" height="140%">
    <feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#000" flood-opacity="0.35"/>
  </filter>
  <filter id="bf"><feGaussianBlur stdDeviation="1.8"/></filter>
  <filter id="bf2"><feGaussianBlur stdDeviation="3.5"/></filter>
  <radialGradient id="sunG" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="${Y}" stop-opacity="0.9"/>
    <stop offset="60%" stop-color="${Y}" stop-opacity="0.2"/>
    <stop offset="100%" stop-color="${Y}" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="skyG" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${B}"/><stop offset="100%" stop-color="${deep}"/>
  </linearGradient>
  <linearGradient id="bronzeG" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${bronzeLight}"/><stop offset="40%" stop-color="${bronze}"/><stop offset="100%" stop-color="${bronzeDark}"/>
  </linearGradient>
  <linearGradient id="pedestalG" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#B8A48A"/><stop offset="50%" stop-color="#8A7A66"/><stop offset="100%" stop-color="#5C5043"/>
  </linearGradient>
  <linearGradient id="storeG" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${B}" stop-opacity="0.85"/><stop offset="100%" stop-color="${deep}" stop-opacity="0.95"/>
  </linearGradient>
  <linearGradient id="flagG" x1="0" y1="0" x2="1" y2="0">
    <stop offset="0%" stop-color="${G}"/><stop offset="50%" stop-color="${Y}"/><stop offset="100%" stop-color="${B}"/>
  </linearGradient>
</defs>`;

// ── SUN / MOON ──
const sunX = w * 0.78;
const sunY = h * 0.16;
const sunR = (18 + 4 * w1) * ww;
if (!isN) {
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR * 2.0}" fill="url(#sunG)"/>`;
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR}" fill="#FFD27A" filter="url(#fg)"/>`;
} else {
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR}" fill="#E8E0D0" opacity="0.4" filter="url(#fg)"/>`;
}

// ── DRIFTING CLOUDS ──
for (let i = 0; i < 5; i++) {
  const cx = ((w * 1.3 * (0.08 + i * 0.22) - mt * 6 * (0.5 + i * 0.12)) % (w * 1.5) + w * 0.05);
  const cy = h * (0.06 + i * 0.04) + sin(mt * 0.25 + i * 0.6, 5);
  const rw = (35 + i * 15 + sin(mt * 0.4 + i, 6)) * ww;
  const rh = (10 + i * 4) * ww;
  svg += `<ellipse cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" rx="${rw.toFixed(1)}" ry="${rh.toFixed(1)}" fill="${white}" opacity="${(0.15 + i * 0.05).toFixed(2)}" filter="url(#bf)"/>`;
  svg += `<ellipse cx="${(cx - rw * 0.3).toFixed(1)}" cy="${(cy - rh * 0.25).toFixed(1)}" rx="${(rw * 0.55).toFixed(1)}" ry="${(rh * 0.65).toFixed(1)}" fill="${white}" opacity="${(0.12 + i * 0.04).toFixed(2)}" filter="url(#bf)"/>`;
}

// ── DISTANT HILLS / LANDSCAPE ──
const bY2 = bY - 6;
svg += `<path d="M0 ${bY2} Q ${w * 0.2} ${bY2 - 35 * ww} ${w * 0.45} ${bY2 - 10} T ${w} ${bY2 - 22} L ${w} ${bY} L 0 ${bY} Z" fill="${G}" opacity="0.20" filter="url(#bf)"/>`;
svg += `<path d="M0 ${bY2 - 8} Q ${w * 0.3} ${bY2 - 55 * ww} ${w * 0.6} ${bY2 - 16} T ${w} ${bY2 - 32} L ${w} ${bY} L 0 ${bY} Z" fill="url(#skyG)" opacity="0.15" filter="url(#bf)"/>`;

// ── HAVAN MEGALOJA (background) ──
const storeW = w * 0.34;
const storeH = h * 0.30;
const storeX = w * 0.56;
const storeY = bY - storeH;
svg += `<rect x="${storeX}" y="${storeY}" width="${storeW}" height="${storeH}" rx="8" fill="url(#storeG)" filter="url(#sh)"/>`;
svg += `<rect x="${storeX}" y="${storeY}" width="${storeW}" height="${storeH * 0.14}" rx="8" fill="${deep}"/>`;
const signW = storeW * 0.44;
const signH = storeH * 0.07;
const signX = storeX + (storeW - signW) * 0.5;
const signY = storeY + storeH * 0.055;
svg += `<rect x="${signX}" y="${signY}" width="${signW}" height="${signH}" rx="3" fill="${Y}" filter="url(#sg)"/>`;
svg += `<text x="${storeX + storeW * 0.5}" y="${(storeY + storeH * 0.115).toFixed(1)}" font-family="Georgia,serif" font-size="${(storeH * 0.058).toFixed(1)}" font-weight="700" fill="${deep}" text-anchor="middle">HAVAN</text>`;
for (let i = 0; i < 6; i++) {
  const wx = storeX + storeW * (0.10 + 0.80 * i / 5);
  const wy = storeY + storeH * 0.22;
  const ww2 = storeW * 0.11;
  const wh = storeH * 0.58;
  svg += `<rect x="${wx.toFixed(1)}" y="${wy.toFixed(1)}" width="${ww2.toFixed(1)}" height="${wh.toFixed(1)}" rx="2" fill="#1A1F2E" stroke="#2A3445" stroke-width="1.2"/>`;
  const glow = isN ? 0.5 + 0.35 * sin(mt * 1.0 + i * 0.8) : 0.65 + 0.2 * sin(mt * 0.6 + i);
  svg += `<rect x="${(wx + 1.5).toFixed(1)}" y="${(wy + 1.5).toFixed(1)}" width="${(ww2 - 3).toFixed(1)}" height="${(wh - 3).toFixed(1)}" rx="1" fill="${Y}" opacity="${clamp(glow, 0.1, 0.85).toFixed(2)}" filter="url(#sg)"/>`;
}

// ── BRAZILIAN FLAG (left of store) ──
const flagX = w * 0.44;
const flagTop = h * 0.24;
const flagPole = bY - flagTop;
svg += `<rect x="${(flagX - 2).toFixed(1)}" y="${flagTop.toFixed(1)}" width="4" height="${flagPole.toFixed(1)}" fill="#A0AAB5" filter="url(#sh)"/>`;
const fW = w * 0.12;
const fH = h * 0.08;
const fx = flagX + 3;
const fy = flagTop + 3;
let flagPath = `M`;
const segs = 16;
for (let i = 0; i <= segs; i++) {
  const t = i / segs;
  const px = fx + fW * t;
  const wave = sin(t * 6 + mt * 1.4, fH * 0.10) * sin(t * Math.PI);
  const py = fy + wave;
  flagPath += `${px.toFixed(1)},${py.toFixed(1)} `;
}
flagPath += `L${(fx + fW).toFixed(1)} ${(fy + fH).toFixed(1)} L${fx.toFixed(1)} ${(fy + fH).toFixed(1)} Z`;
svg += `<path d="${flagPath}" fill="url(#flagG)" filter="url(#sh)"/>`;
const dR = fH * 0.28;
svg += `<circle cx="${(fx + fW * 0.5).toFixed(1)}" cy="${(fy + fH * 0.5).toFixed(1)}" r="${dR.toFixed(1)}" fill="${B}" opacity="0.7"/>`;
svg += `<path d="M${(fx + fW * 0.5).toFixed(1)} ${(fy + fH * 0.5 - dR).toFixed(1)} L${(fx + fW * 0.5 + dR * 0.9).toFixed(1)} ${(fy + fH * 0.5).toFixed(1)} L${(fx + fW * 0.5).toFixed(1)} ${(fy + fH * 0.5 + dR).toFixed(1)} L${(fx + fW * 0.5 - dR * 0.9).toFixed(1)} ${(fy + fH * 0.5).toFixed(1)} Z" fill="${white}" opacity="0.6"/>`;

// ── PALM TREES ──
for (let side of [-1, 1]) {
  const tx = (side === -1 ? w * 0.08 : w * 0.92);
  const sway = sin(mt * 0.6 + side * 0.4, 2.5);
  const trunkH = 65 * ww;
  svg += `<path d="M${tx.toFixed(1)} ${(bY - 3).toFixed(1)} Q ${(tx + sway).toFixed(1)} ${(bY - trunkH * 0.5).toFixed(1)} ${(tx + sway * 1.3).toFixed(1)} ${(bY - trunkH).toFixed(1)}" stroke="#5C4033" stroke-width="${(5.5 * ww).toFixed(1)}" fill="none" stroke-linecap="round" filter="url(#sh)"/>`;
  for (let k = 0; k < 5; k++) {
    const ang = -1.8 + k * 0.9 + sin(mt * 0.5 + side + k, 0.03);
    const lx = tx + sway * 1.3 + cos(ang, 24 * ww);
    const ly = bY - trunkH + sin(ang, 16 * ww);
    svg += `<line x1="${(tx + sway * 1.3).toFixed(1)}" y1="${(bY - trunkH).toFixed(1)}" x2="${lx.toFixed(1)}" y2="${ly.toFixed(1)}" stroke="#2E7D52" stroke-width="${(2.8 * ww).toFixed(1)}" stroke-linecap="round"/>`;
  }
}

// ═══════════════════════════════════════════════════════
// ── HERO: BRONZE STATUE OF LUCIANO HANG ──
// ═══════════════════════════════════════════════════════
const statX = w * 0.30;
const statBase = bY - 4;
const s = 1.6;

// Breathing organic animation
const breathe = sin(mt * 1.2, 1.5 * s);
const statY = statBase + breathe;

// ── PEDESTAL ──
const pedW = 32 * s * ww;
const pedH = 22 * s * ww;
const pedX = statX - pedW / 2;
const pedY = statY - pedH;

// Pedestal shadow
svg += `<ellipse cx="${statX.toFixed(1)}" cy="${(statBase + 2).toFixed(1)}" rx="${(pedW * 0.6).toFixed(1)}" ry="${(6 * s * ww).toFixed(1)}" fill="rgba(0,0,0,0.25)" filter="url(#bf2)"/>`;

// Pedestal body
svg += `<rect x="${pedX.toFixed(1)}" y="${pedY.toFixed(1)}" width="${pedW.toFixed(1)}" height="${pedH.toFixed(1)}" rx="3" fill="url(#pedestalG)" filter="url(#sh)"/>`;
svg += `<rect x="${(pedX + 2).toFixed(1)}" y="${(pedY + 3).toFixed(1)}" width="${(pedW - 4).toFixed(1)}" height="3" fill="rgba(255,255,255,0.12)"/>`;

// Plaque
const plaqueW = pedW * 0.7;
const plaqueH = pedH * 0.25;
const plaqueX = statX - plaqueW / 2;
const plaqueY = pedY + pedH * 0.55;
svg += `<rect x="${plaqueX.toFixed(1)}" y="${plaqueY.toFixed(1)}" width="${plaqueW.toFixed(1)}" height="${plaqueH.toFixed(1)}" rx="2" fill="${bronzeDark}" stroke="${bronzeLight}" stroke-width="1"/>`;
svg += `<text x="${statX.toFixed(1)}" y="${(plaqueY + plaqueH * 0.42).toFixed(1)}" font-family="Georgia,serif" font-size="${(plaqueH * 0.3).toFixed(1)}" font-weight="600" fill="${bronzeLight}" text-anchor="middle">LUCIANO HANG</text>`;
svg += `<text x="${statX.toFixed(1)}" y="${(plaqueY + plaqueH * 0.78).toFixed(1)}" font-family="Georgia,serif" font-size="${(plaqueH * 0.22).toFixed(1)}" fill="${bronze}" text-anchor="middle">EMPREENDEDOR</text>`;

// ── STATUE BODY (bronze silhouette — standing proud posture) ──
const bodyX = statX;
const bodyY = pedY - 2;
const sh = 52 * s * ww;

// Legs (trousers)
svg += `<rect x="${(bodyX - 8 * s * ww).toFixed(1)}" y="${(bodyY - sh * 0.28).toFixed(1)}" width="${(6 * s * ww).toFixed(1)}" height="${(sh * 0.28).toFixed(1)}" rx="${(2 * s * ww).toFixed(1)}" fill="url(#bronzeG)" filter="url(#sh)"/>`;
svg += `<rect x="${(bodyX + 2 * s * ww).toFixed(1)}" y="${(bodyY - sh * 0.28).toFixed(1)}" width="${(6 * s * ww).toFixed(1)}" height="${(sh * 0.28).toFixed(1)}" rx="${(2 * s * ww).toFixed(1)}" fill="url(#bronzeG)" filter="url(#sh)"/>`;

// Shoes
svg += `<rect x="${(bodyX - 10 * s * ww).toFixed(1)}" y="${(bodyY - 1).toFixed(1)}" width="${(9 * s * ww).toFixed(1)}" height="${(3 * s * ww).toFixed(1)}" rx="${(1.5 * s * ww).toFixed(1)}" fill="${bronzeDark}"/>`;
svg += `<rect x="${(bodyX + 1 * s * ww).toFixed(1)}" y="${(bodyY - 1).toFixed(1)}" width="${(9 * s * ww).toFixed(1)}" height="${(3 * s * ww).toFixed(1)}" rx="${(1.5 * s * ww).toFixed(1)}" fill="${bronzeDark}"/>`;

// Torso (suit jacket)
svg += `<path d="M${(bodyX - 10 * s * ww).toFixed(1)} ${(bodyY - sh * 0.28).toFixed(1)} L${(bodyX - 9 * s * ww).toFixed(1)} ${(bodyY - sh * 0.68).toFixed(1)} Q${bodyX.toFixed(1)} ${(bodyY - sh * 0.75).toFixed(1)} ${(bodyX + 9 * s * ww).toFixed(1)} ${(bodyY - sh * 0.68).toFixed(1)} L${(bodyX + 10 * s * ww).toFixed(1)} ${(bodyY - sh * 0.28).toFixed(1)} Z" fill="url(#bronzeG)" filter="url(#sh)"/>`;

// Arms
for (let side of [-1, 1]) {
  const ax = bodyX + side * 11 * s * ww;
  const ayTop = bodyY - sh * 0.65;
  const ayBot = bodyY - sh * 0.25 + sin(mt * 1.5 + side, 1.5 * s * ww);
  svg += `<path d="M${ax.toFixed(1)} ${ayTop.toFixed(1)} Q${(ax + side * 3 * s * ww).toFixed(1)} ${((ayTop + ayBot) / 2).toFixed(1)} ${ax.toFixed(1)} ${ayBot.toFixed(1)}" stroke="url(#bronzeG)" stroke-width="${(4 * s * ww).toFixed(1)}" fill="none" stroke-linecap="round" filter="url(#sh)"/>`;
  // Hand (open, welcoming)
  svg += `<circle cx="${ax.toFixed(1)}" cy="${ayBot.toFixed(1)}" r="${(2.5 * s * ww).toFixed(1)}" fill="${bronzeLight}"/>`;
}

// Head
const headR = 7 * s * ww;
const headY = bodyY - sh * 0.78;
svg += `<circle cx="${bodyX.toFixed(1)}" cy="${headY.toFixed(1)}" r="${headR.toFixed(1)}" fill="url(#bronzeG)" filter="url(#sh)"/>`;

// Hair
svg += `<path d="M${(bodyX - headR).toFixed(1)} ${headY.toFixed(1)} Q${(bodyX - headR * 0.5).toFixed(1)} ${(headY - headR * 1.2).toFixed(1)} ${(bodyX + headR * 0.5).toFixed(1)} ${(headY - headR * 1.2).toFixed(1)} Q${(bodyX + headR).toFixed(1)} ${headY.toFixed(1)} ${(bodyX + headR).toFixed(1)} ${headY.toFixed(1)}" fill="${bronzeDark}" filter="url(#sh)"/>`;

// Eyes (deterministic blink via mt)
const eyeOpen = sin(mt * 1.8) > 0.94 ? 0.15 : 1;
for (let side of [-1, 1]) {
  const eyeX = bodyX + side * 3 * s * ww;
  const eyeY = headY + 1.5 * s * ww;
  svg += `<ellipse cx="${eyeX.toFixed(1)}" cy="${eyeY.toFixed(1)}" rx="${(1.5 * s * ww).toFixed(1)}" ry="${(1.5 * s * ww * eyeOpen).toFixed(1)}" fill="${bronzeDark}"/>`;
}

// Nose
svg += `<path d="M${bodyX.toFixed(1)} ${(headY + 1.5 * s * ww).toFixed(1)} L${bodyX.toFixed(1)} ${(headY + 4 * s * ww).toFixed(1)}" stroke="${bronzeDark}" stroke-width="${(1.5 * s * ww).toFixed(1)}" stroke-linecap="round"/>`;

// Smile (organic, slight movement)
const smileH = 0.8 + sin(mt * 0.7, 0.3);
svg += `<path d="M${(bodyX - 3 * s * ww).toFixed(1)} ${(headY + 3.5 * s * ww).toFixed(1)} Q${bodyX.toFixed(1)} ${(headY + 3.5 * s * ww + smileH * s * ww).toFixed(1)} ${(bodyX + 3 * s * ww).toFixed(1)} ${(headY + 3.5 * s * ww).toFixed(1)}" stroke="${bronzeDark}" stroke-width="${(1.2 * s * ww).toFixed(1)}" fill="none" stroke-linecap="round"/>`;

// Tie
svg += `<path d="M${(bodyX - 1.8 * s * ww).toFixed(1)} ${(bodyY - sh * 0.68).toFixed(1)} L${bodyX.toFixed(1)} ${(bodyY - sh * 0.55).toFixed(1)} L${(bodyX + 1.8 * s * ww).toFixed(1)} ${(bodyY - sh * 0.68).toFixed(1)} Z" fill="${bronzeDark}" opacity="0.8"/>`;
svg += `<rect x="${(bodyX - 1.2 * s * ww).toFixed(1)}" y="${(bodyY - sh * 0.55).toFixed(1)}" width="${(2.4 * s * ww).toFixed(1)}" height="${(sh * 0.06).toFixed(1)}" rx="${(0.6 * s * ww).toFixed(1)}" fill="${bronzeDark}" opacity="0.7"/>`;

// ── SPARKLE / SUNLIGHT GLINT ON STATUE ──
const glint = 0.3 + sin(mt * 2.0) * 0.15;
svg += `<circle cx="${(bodyX - 4 * s * ww).toFixed(1)}" cy="${(headY - headR * 0.7).toFixed(1)}" r="${(1.5 * s * ww).toFixed(1)}" fill="${Y}" opacity="${clamp(glint, 0.1, 0.5).toFixed(2)}" filter="url(#fg)"/>`;

// ═══════════════════════════════════════════════════════
// ── FOREGROUND: FLOWER BEDS / ORNAMENTAL PLANTS ──
// ═══════════════════════════════════════════════════════
for (let side of [-1, 1]) {
  const bx = statX + side * 28 * s * ww;
  const by = statBase;
  for (let j = 0; j < 5; j++) {
    const px = bx + (j - 2) * 5 * ww + sin(mt * 0.9 + j * 0.7, 2 * ww);
    const py = by - (6 + (j % 3) * 3) * ww + sin(mt * 1.1 + j * 0.5, 1.5 * ww);
    const cc = j % 2 === 0 ? Y : j % 3 === 0 ? '#E8A87C' : '#F4D03F';
    svg += `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="${(2.5 * ww).toFixed(1)}" fill="${cc}" opacity="${(0.7 + sin(mt * 1.5 + j) * 0.15).toFixed(2)}" filter="url(#sg)"/>`;
  }
}

// ── FOREGROUND GRASS TEXTURE ──
for (let i = 0; i < 14; i++) {
  const gx = (i * w / 13 + sin(mt * 0.2 + i * 0.9, 5 * ww)) % w;
  const gh = (4 + (i % 4) * 2) * ww + sin(mt * 0.5 + i * 1.1, 1.5 * ww);
  svg += `<path d="M${gx.toFixed(1)} ${(bY - 1).toFixed(1)} Q${(gx + 1.5 * ww).toFixed(1)} ${(bY - gh * 0.6).toFixed(1)} ${(gx + sin(mt * 0.3 + i, 2 * ww)).toFixed(1)} ${(bY - gh).toFixed(1)}" stroke="${G}" stroke-width="${(1.5 * ww).toFixed(1)}" fill="none" opacity="${(0.5 + sin(mt * 0.4 + i, 0.15)).toFixed(2)}" stroke-linecap="round"/>`;
}

// ── GROUND PATH (cobblestone walkway to statue) ──
const pathW = 28 * ww;
const pathX = statX - pathW / 2;
svg += `<rect x="${pathX.toFixed(1)}" y="${(statBase - 2).toFixed(1)}" width="${pathW.toFixed(1)}" height="${(h - statBase + 2).toFixed(1)}" fill="#8A7A66" opacity="0.4" filter="url(#bf)"/>`;
for (let i = 0; i < 8; i++) {
  const sx = pathX + (i % 2) * 8 * ww + sin(mt * 0.15 + i, 2 * ww);
  const sy = statBase + 4 + i * 5 * ww;
  svg += `<ellipse cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" rx="${(3 * ww).toFixed(1)}" ry="${(1.5 * ww).toFixed(1)}" fill="#6B5D4F" opacity="0.4"/>`;
}

// ── FLOATING CONFETTI / PARTICLES (organic feel) ──
for (let i = 0; i < 6; i++) {
  const px = (w * ((i * 0.17 + 0.04) % 1) + sin(mt * 0.25 + i * 1.4, 14 * ww)) % w;
  const py = (h * 0.25 + (mt * 18 + i * 55) % (h * 0.50));
  const pr = 1.8 + (i % 3) * 1.0;
  const cc = i % 3 === 0 ? Y : i % 3 === 1 ? '#FF6B6B' : '#4ECDC4';
  svg += `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="${pr.toFixed(1)}" fill="${cc}" opacity="${(0.3 + sin(mt * 1.0 + i) * 0.12).toFixed(2)}" filter="url(#sg)"/>`;
}

return svg;
